        "zh" to GemDetails(
            "柱晶石（kornerupine）是一种成分复杂的镁铝硼硅酸盐。它形成于高级变质岩——富镁富铝的麻粒岩和片麻岩——中：地壳深部的高温高压使含硼的古老沉积物发生反应；常与假蓝宝石、刚玉、堇青石和矽线石共生。经侵蚀释出后，富集于冲积砾石中。颜色为黄绿至翠绿（钒、铬致色）、褐色，较少见蓝绿色。其名纪念丹麦探险家安德烈亚斯·科内鲁普（Andreas Kornerup）。",
            "斜方晶系。长柱状晶体，常被磨圆；也有纤维状集合体。两组良好解理；断口贝壳状至参差状。硬度6至7；密度3.27至3.45；玻璃光泽；折射率1.660至1.699；双折射率0.012至0.017（二轴晶）。多色性强，随角度呈绿、黄和红褐色，切磨时须注意定向。针状包体可形成罕见的猫眼或星光柱晶石。它稀少且鲜为人知，是因颜色和硬度尚佳而受青睐的收藏宝石。",
            "斯里兰卡：拉特纳普勒宝石砾石，产绿褐色宝石和猫眼。马达加斯加：多凡堡（托拉纳鲁、伊霍西）一带，产绿色和蓝绿色宝石。坦桑尼亚：翁巴谷和莫罗戈罗地区，产含钒的鲜绿色宝石。肯尼亚（夸莱）、缅甸（抹谷）、印度、格陵兰（模式产地菲斯克内塞）和南非亦有产出。",
            "象征动力、学习与表达，据说能激发创造力、在需要付出努力的时期给予支持。它与心轮、喉轮及天蝎座相关联。可用水或烟熏净化；可在柔和阳光下充能。"
        )
    )

    private fun hyperstene() = mapOf(
        "fr" to GemDetails(
